import{z as l,x as s,o as B,c as d,q as t,j as A,D as e,d as n,s as o,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"引力模型","description":"","frontmatter":{"title":"引力模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gravity-model.md","filePath":"econ/gravity-model.md","lastUpdated":1791063341000}'),p={name:"econ/gravity-model.md"};function m(D,E,F,_,u,C){const i=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="引力模型" tabindex="-1">引力模型 <a class="header-anchor" href="#引力模型" aria-label="Permalink to &quot;引力模型&quot;">​</a></h1><div class="epigraph"><p>双边贸易随经济规模升、随距离与边界降；这不是天体力学的比喻课，而是支出份额与市场进入成本加总之后的会计。</p><footer>—— Tinbergen 经验引力；Anderson and van Wincoop, Gravity with Gravitas, AER 2003</footer></div><p><a href="/econ/melitz-heterogeneous-firms">上一课</a>在企业层给出选择。本课把双边流量写成可估计的引力。Eaton–Kortum 下一课给李嘉图微观基础的另一种加总。本课钉：结构引力与多边阻力，禁止把距离弹性当因果魔法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经验上 \\(X_{ij}\\propto Y_i Y_j/\\mathrm{dist}_{ij}^\\zeta\\)。Tinbergen 当描述。Anderson–van Wincoop：CES 需求下，双边出口还依赖<strong>多边阻力</strong>——\\(i\\) 进入所有市场的成本、\\(j\\) 从所有来源购买的成本。漏掉它们，距离与边界的系数有偏（边境之谜被夸大）。缺口不是再讲 Melitz 门槛，而是：加总之后，任何产生 CES 或类似支出份额的模型都会长出引力；估计必须处理多边阻力（固定效应或显式价格指数）。</p><p><span class="marginnote">直觉类比：两国贸易像两座城市间的客流量——城市越大（GDP 越大），来往越多；离得越远、过路费越贵（距离、关税、语言），来往越少。Tinbergen 借的是牛顿引力「质量大则引力大、距离远则引力小」的形，但系数是估出来的，不是宇宙常数。</span></p><p><span class="marginnote">Head–Mayer 综述：引力是贸易经验的骨干。PPML（Santos Silva–Tenreyro）处理零贸易与异方差，OLS 对数会扔零、且 Jensen 不等式偏误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>结构：\\(\\ln X_{ij}=\\ln S_i+\\ln M_j+\\ln \\tau_{ij}^{1-\\sigma}+\\varepsilon_{ij}\\)，\\(S_i,M_j\\) 用进出口固定效应吸收。\\(\\tau_{ij}\\) 含距离、边界、语言、关税、协定。因果：关税与协定仍要识别（后课 WTO、China shock），引力方程本身先是均衡加总。一般均衡反事实：改 \\(\\tau\\)，重解所有多边阻力（Dekle–Eaton–Kortum 精确帽子代数），不是只看双边偏效应。</p><p><span class="marginnote">术语翻译：PPML（泊松伪极大似然）是引力估计的常用方法，直接对贸易额建模，可以保留「贸易额为 0」的观测；老式做法取对数，\\(\\ln 0\\) 没有定义，只能整行扔掉——而零贸易（某些国家对根本不做某类生意）往往正是最有信息量的样本。</span></p>',10)),(B(),A(r,null,{default:e(()=>[o(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CES%5B%22%E6%94%AF%E5%87%BA%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20GRV%5B%22%E5%8F%8C%E8%BE%B9%20X_ij%22%5D%0A%20%20SIZE%5B%22%E8%A7%84%E6%A8%A1%20Y%22%5D%20--%3E%20GRV%0A%20%20TAU%5B%22%E8%B4%B8%E6%98%93%E6%88%90%E6%9C%AC%20%CF%84%22%5D%20--%3E%20GRV%0A%20%20MR%5B%22%E5%A4%9A%E8%BE%B9%E9%98%BB%E5%8A%9B%22%5D%20--%3E%20BIAS%5B%22%E6%BC%8F%E6%8E%89%E5%88%99%E8%B7%9D%E7%A6%BB%2F%E8%BE%B9%E5%A2%83%E5%81%8F%22%5D%0A%20%20FE%5B%22%E8%BF%9B%E5%87%BA%E5%8F%A3%20FE%22%5D%20--%3E%20MR%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"与计量：国家–产品–时间面板上的政策可以用 DiD，但必须与多边阻力共存（三元固定效应）。本课不重写交错 DiD。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"机制是份额。\\(j\\) 的支出在来源 \\(i\\) 上的份额随相对 \\(\\tau_{ij}\\) 与相对价格变。距离进入 \\(\\tau\\)，所以流量随距离降。规模进入支出与供给能力。零贸易：Melitz 选择使部分 \\(ij\\) 对为零，引力在广延边际也成立（Helpman–Melitz–Rubinstein）。EK 下一课用极值生产率抽签给出另一套闭式份额。",-1)),E[6]||(E[6]=a("p",null,"边境效应大：可以是真实政策壁垒、可以是可加贸易成本在短距离上更显眼、可以是多边阻力误设。Anderson–van Wincoop 显示：正确计入阻力后，美加边境仍在，但小于朴素回归。",-1)),(B(),A(r,null,{default:e(()=>[o(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%EF%BC%9A%E7%BE%8E%E5%8A%A0%E5%8F%8C%E8%BE%B9%E8%B4%B8%E6%98%93%E8%BF%9C%E5%B0%8F%E4%BA%8E%E5%90%84%E8%87%AA%E5%9B%BD%E5%86%85%E8%B4%B8%E6%98%93%22%5D%20--%3E%20NAIVE%5B%22%E6%9C%B4%E7%B4%A0%E5%9B%9E%E5%BD%92%EF%BC%9A%E5%8F%AA%E6%94%BE%E8%B7%9D%E7%A6%BB%E4%B8%8E%E8%BE%B9%E5%A2%83%E8%99%9A%E6%8B%9F%E5%8F%98%E9%87%8F%22%5D%0A%20%20OBS%20--%3E%20STRUCT%5B%22%E7%BB%93%E6%9E%84%E4%BC%B0%E8%AE%A1%EF%BC%9A%E8%BF%9B%E5%87%BA%E5%8F%A3%E5%9B%BA%E5%AE%9A%E6%95%88%E5%BA%94%E5%90%B8%E6%94%B6%20S_i%20%E4%B8%8E%20M_j%22%5D%0A%20%20NAIVE%20--%3E%20OVER%5B%22%E8%BE%B9%E5%A2%83%E6%95%88%E5%BA%94%E8%A2%AB%E5%A4%B8%E5%A4%A7%EF%BC%9A%E6%B2%A1%E7%AE%97%E5%8A%A0%E6%8B%BF%E5%A4%A7%E3%80%8E%E9%99%A4%E4%BA%86%E7%BE%8E%E5%9B%BD%E8%BF%98%E8%83%BD%E5%90%91%E8%B0%81%E4%B9%B0%E3%80%8F%22%5D%0A%20%20STRUCT%20--%3E%20FIX%5B%22%E9%87%8D%E8%A7%A3%E5%A4%9A%E8%BE%B9%E9%98%BB%E5%8A%9B%EF%BC%9A%E8%BE%B9%E5%A2%83%E4%BB%8D%E5%9C%A8%EF%BC%8C%E4%BD%86%E5%B0%8F%E5%BE%97%E5%A4%9A%22%5D%0A%20%20OVER%20--%3E%20MORAL%5B%22%E5%BC%95%E5%8A%9B%E7%B3%BB%E6%95%B0%E6%98%AF%E5%9D%87%E8%A1%A1%E5%8A%A0%E6%80%BB%EF%BC%8C%E4%B8%8D%E6%98%AF%E7%89%9B%E9%A1%BF%E5%B8%B8%E6%95%B0%22%5D%0A%20%20FIX%20--%3E%20MORAL%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">数字实例：只看美加贸易对 GDP 之比偏低，就说「边境杀死了九成贸易」是危险的：加拿大的对外贸易被距离整体压着，正确的基准是「若无边境，它本可以从其他来源买多少」。把这个替代基准（多边阻力）计入后，同一份数据算出的边境损耗明显变小。</span></p><p><span class="marginnote">不要把引力写成牛顿定律。\\(\\zeta\\) 随 \\(\\sigma\\) 与 \\(\\tau\\) 的函数形式变。结构反事实要的是贸易弹性 \\(\\sigma-1\\)，不是某一个距离系数的永恒值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 FTA 的系数当成福利。福利要进关税与条款课的一般均衡。下一课 Eaton–Kortum 把李嘉图随机化，引力从极值分布长出。不要用引力吞并量化栏的运费或提单微观结构。</p><p>后课默认：双边流量用带多边阻力的引力；对数 OLS 丢零是问题；政策反事实要重解阻力，不是读一个 \\(\\tau\\) 系数当充分统计。企业选择与引力加总兼容。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引力：规模促进、距离与壁垒抑制；来自支出份额加总。</li><li>多边阻力必须进估计，否则边境与距离偏。</li><li>PPML 与固定效应处理零与阻力。</li><li>反事实是一般均衡帽子代数，不是偏系数。</li><li>出处：Tinbergen；Anderson and van Wincoop, <em>AER</em> 2003；Santos Silva and Tenreyro；Head and Mayer。</li></ul>',7))])}const S=l(p,[["render",m]]);export{T as __pageData,S as default};
